INSERT OR IGNORE INTO memories
  (id, user_id, title, content, location_name, memory_date, emotion, visibility,
   is_anonymous, location_precision, latitude, longitude, public_latitude,
   public_longitude, created_at, updated_at)
VALUES
  ('20000000-0000-4000-8000-000000000001', 'demo-user-1', '시험이 끝난 뒤의 밤 산책', '마지막 시험이 끝났는데도 바로 집에 가기는 아쉬웠다. 편의점에서 음료를 하나씩 들고 태화강 쪽으로 걸었다. 시험 얘기는 금방 끝났고, 별것 아닌 농담으로 한참을 웃었다.

강바람이 생각보다 차가웠다. 돌아갈 때쯤엔 발이 조금 아팠지만 누구도 먼저 가자는 말을 하지 않았다. 그날 무슨 얘기를 했는지는 흐릿한데, 이제 한동안 알람을 맞추지 않아도 된다는 해방감은 아직 선명하다.', '태화강 국가정원', '2019-06-21', 'peaceful', 'public', 1, 'approximate', 35.5532, 129.2924, 35.55, 129.29, '2026-09-10T00:00:00.000Z', '2026-09-10T00:00:00.000Z'),
  ('20000000-0000-4000-8000-000000000002', 'demo-user-2', '파도 소리가 오래 남은 오후', '대왕암 끝까지 걸어가서 한동안 난간에 기대 있었다. 바위에 부딪히는 파도를 보고 있으면 같은 장면이 계속 달라지는 게 신기했다. 사진을 찍으려고 폰을 꺼냈다가 그냥 주머니에 넣었다.

집에 와서는 바다보다 돌아오는 길이 먼저 떠올랐다. 신발 안에 들어간 모래, 조금 짰던 입술, 저녁으로 뭘 먹을지 고르던 목소리. 별일 없던 오후가 이렇게 오래 남을 줄은 몰랐다.', '대왕암공원', '2021-10-16', 'meaningful', 'public', 0, 'exact', 35.4926, 129.4391, 35.4926, 129.4391, '2026-09-10T00:00:00.000Z', '2026-09-10T00:00:00.000Z'),
  ('20000000-0000-4000-8000-000000000005', 'demo-user-3', '가족과 처음 찾은 정원', '가족이 다 같이 나온 게 얼마 만인지 모르겠다. 엄마는 꽃 이름을 물었고 아빠는 아는 척하다가 결국 안내판을 읽었다. 나는 그 모습이 웃겨서 뒤에서 몰래 사진을 찍었다.

정원을 다 둘러보겠다고 했는데 중간 벤치에 앉은 시간이 더 길었다. 가져온 귤을 나눠 먹고, 다음에는 언제 오자는 얘기를 했다. 사진을 넘겨 보면 풍경보다 서로를 기다려 주던 뒷모습에서 자꾸 손이 멈춘다.', '태화강 국가정원', '2020-10-04', 'happy', 'public', 0, 'exact', 35.5502, 129.2903, 35.5502, 129.2903, '2026-09-10T00:00:00.000Z', '2026-09-10T00:00:00.000Z'),
  ('20000000-0000-4000-8000-000000000006', 'demo-user-1', '혼자 달린 자전거 길', '머릿속이 시끄러워서 자전거를 끌고 나왔다. 어디까지 갈지는 정하지 않고 강을 따라 페달만 밟았다. 앞에서 달리던 사람과 거리가 벌어지자 그제야 내 숨소리가 들렸다.

문제가 해결된 건 아니었다. 그래도 돌아오는 길에는 오늘 안에 답을 내리지 않아도 괜찮겠다는 생각이 들었다. 자전거를 세우고 마신 물이 유난히 시원했다.', '태화강 국가정원 산책로', '2022-08-27', 'lonely', 'public', 1, 'exact', 35.5503, 129.2897, 35.5503, 129.2897, '2026-09-10T00:00:00.000Z', '2026-09-10T00:00:00.000Z'),
  ('20000000-0000-4000-8000-000000000007', 'demo-user-2', '처음 마주한 봄 꽃밭', '꽃이 이렇게 많이 피어 있을 줄 몰랐다. 늘 지나던 길인데 오늘은 모퉁이를 돌자마자 발이 멈췄다. 색이 너무 선명해서 사진에 담으면 오히려 덜 예쁠 것 같았다.

같이 온 친구에게 저기 좀 보라고 몇 번이나 말했다. 친구는 이미 보고 있다며 웃었다. 봄이 왔다는 말을 달력보다 먼저 실감한 날이었다.', '태화강 국가정원', '2023-04-09', 'excited', 'public', 0, 'exact', 35.5498, 129.2905, 35.5498, 129.2905, '2026-09-10T00:00:00.000Z', '2026-09-10T00:00:00.000Z'),
  ('20000000-0000-4000-8000-000000000008', 'demo-user-3', '오래된 친구와 다시 만난 곳', '만나기 전에는 조금 어색할까 봐 걱정했다. 마지막으로 본 뒤 서로의 생활이 꽤 많이 달라졌으니까. 그런데 얼굴을 보자마자 예전 별명부터 나와 버렸다.

강변을 두 바퀴나 도는 동안 못 했던 얘기를 나눴다. 헤어질 때 다음에는 이렇게 오래 미루지 말자고 했다. 집에 도착하니 먼저 잘 들어갔냐는 연락이 와 있었다.', '태화강 국가정원 산책로', '2025-09-13', 'love', 'public', 1, 'exact', 35.5497, 129.2896, 35.5497, 129.2896, '2026-09-10T00:00:00.000Z', '2026-09-10T00:00:00.000Z'),
  ('20000000-0000-4000-8000-000000000009', 'demo-user-1', '비가 그친 뒤의 잔디 냄새', '비가 그치기를 기다리다 늦게 공원에 갔다. 벤치는 아직 젖어 있었고 나무 밑을 지날 때마다 물방울이 떨어졌다. 그냥 돌아갈까 하다가 한 바퀴만 더 걷기로 했다.

잔디 냄새가 진해서 어릴 때 비 오는 날 운동장에 나갔던 일이 생각났다. 오래 잊고 있던 장면이 냄새 하나에 돌아온다는 게 이상했다. 우산은 끝내 다시 펴지 않았다.', '울산대공원', '2018-07-14', 'nostalgic', 'public', 0, 'exact', 35.5317, 129.2935, 35.5317, 129.2935, '2026-09-10T00:00:00.000Z', '2026-09-10T00:00:00.000Z'),
  ('20000000-0000-4000-8000-000000000010', 'demo-user-2', '골목의 작은 불빛', '어느 계절이었는지는 잘 기억나지 않는다. 성남동 골목에서 약속 시간을 기다리며 천천히 걷던 저녁이었다. 가게들이 하나둘 불을 켜는데, 유리창마다 안쪽 풍경이 달랐다.

빵 봉투를 든 사람과 마주쳐 길을 비켜 주고, 이름 모를 노래가 들리는 가게 앞에서 잠깐 멈췄다. 누굴 기다렸는지보다 그때 혼자 있어도 외롭지 않았다는 마음이 더 또렷하다.', '성남동 문화의거리', NULL, 'meaningful', 'public', 1, 'approximate', 35.5558, 129.3193, 35.56, 129.32, '2026-09-10T00:00:00.000Z', '2026-09-10T00:00:00.000Z'),
  ('20000000-0000-4000-8000-000000000011', 'demo-user-3', '수업이 끝난 늦은 오후', '수업이 일찍 끝나서 정류장까지 일부러 돌아갔다. 교재는 무거웠지만 곧장 버스를 타고 싶지는 않았다. 캠퍼스 담장 옆에 새로 생긴 가게를 구경하고, 다음 학기에 듣고 싶은 수업을 생각했다.

그때는 하루가 늘 비슷하다고 투덜댔다. 지금 돌아보면 그렇게 빈 시간이 생기던 오후가 조금 그립다. 아무 계획 없이 걸을 수 있다는 것도 여유였는데.', '울산대학교 주변', '2024-03-22', 'meaningful', 'public', 0, 'exact', 35.5438, 129.2592, 35.5438, 129.2592, '2026-09-10T00:00:00.000Z', '2026-09-10T00:00:00.000Z'),
  ('20000000-0000-4000-8000-000000000012', 'demo-user-1', '여름 저녁의 모래사장', '해가 넘어갈 때까지 해변에 앉아 있었다. 옆에서는 아이들이 모래를 파고 있었고 우리는 녹아 가는 아이스크림을 급하게 먹었다. 손이 끈적해져서 서로 휴지를 찾다가 웃었다.

조금 더 있다 가자는 말을 번갈아 했다. 특별히 한 일은 없는데 집에 돌아와 보니 하루를 잘 보냈다는 기분이 들었다. 그날의 바다는 파란색보다 저녁빛에 가까웠다.', '일산해수욕장', '2025-08-02', 'happy', 'public', 1, 'exact', 35.4975, 129.4283, 35.4975, 129.4283, '2026-09-10T00:00:00.000Z', '2026-09-10T00:00:00.000Z'),
  ('20000000-0000-4000-8000-000000000015', 'demo-user-2', '햇살이 따뜻했던 공원 벤치', '새 학기 계획을 세우겠다고 노트를 챙겨 공원에 갔다. 햇볕이 드는 벤치에 앉으니 계획보다 점심 메뉴가 먼저 떠올랐다. 한참 뒤에야 첫 줄을 썼다. 일주일에 한 번은 이렇게 밖에 나오기.

거창한 목표를 적지 않아서 오히려 마음에 들었다. 노트 사이에 끼운 영수증을 볼 때마다 그날 벤치가 얼마나 따뜻했는지 생각난다.', '울산대공원', '2026-03-07', 'happy', 'public', 1, 'exact', 35.5322, 129.2941, 35.5322, 129.2941, '2026-09-10T00:00:00.000Z', '2026-09-10T00:00:00.000Z'),
  ('20000000-0000-4000-8000-000000000099', 'local_seedy', '나만 간직한 골목의 저녁', '집에 거의 다 와서 골목 입구에 잠깐 서 있었다. 창문 사이로 저녁 준비하는 소리가 들렸다. 오늘 있었던 일을 누구에게 말할까 생각하다가 그냥 마음에만 남겨 두기로 했다.

아무 일도 없었던 것처럼 문을 열고 들어갔다. 그래도 그 골목에서 숨을 고르던 몇 분은 내게 필요했다. 나중에 내가 잊어버릴까 봐 여기 적어 둔다.', '울산 주택가 골목', '2022-11-03', 'nostalgic', 'private', 0, 'exact', 35.5412, 129.3051, 35.5412, 129.3051, '2026-09-10T00:00:00.000Z', '2026-09-10T00:00:00.000Z');
